  1→//! HTTP template fetching.
  2→//!
  3→//! Provides an HTTP client for fetching templates from URLs with
  4→//! support for ETag-based conditional requests.
  5→
  6→use anyhow::{bail, Result};
  7→use reqwest::blocking::Client;
  8→use std::time::Duration;
  9→
 10→/// Default maximum response body size (10 MB).
 11→const DEFAULT_MAX_RESPONSE_SIZE: u64 = 10 * 1024 * 1024;
 12→
 13→/// Fetches templates over HTTP/HTTPS.
 14→pub struct HttpFetcher {
 15→    client: Client,
 16→    timeout: Duration,
 17→    max_response_size: u64,
 18→}
 19→
 20→/// Response from fetching a template.
 21→#[derive(Debug)]
 22→pub struct FetchResponse {
 23→    /// The template content.
 24→    pub content: String,
 25→    /// ETag header if present.
 26→    pub etag: Option<String>,
 27→    /// Last-Modified header if present.
 28→    pub last_modified: Option<String>,
 29→}
 30→
 31→impl HttpFetcher {
 32→    /// Create a new HTTP fetcher with default 30-second timeout.
 33→    pub fn new() -> Self {
 34→        Self::with_timeout(Duration::from_secs(30))
 35→    }
 36→
 37→    /// Create a new HTTP fetcher with custom timeout.
 38→    pub fn with_timeout(timeout: Duration) -> Self {
 39→        Self {
 40→            client: Client::builder()
 41→                .user_agent("bivvy")
 42→                .timeout(timeout)
 43→                .build()
 44→                .expect("Failed to build HTTP client"),
 45→            timeout,
 46→            max_response_size: DEFAULT_MAX_RESPONSE_SIZE,
 47→        }
 48→    }
 49→
 50→    /// Create a new HTTP fetcher with custom timeout and max response size.
 51→    #[cfg(test)]
 52→    pub fn with_max_size(timeout: Duration, max_response_size: u64) -> Self {
 53→        Self {
 54→            client: Client::builder()
 55→                .user_agent("bivvy")
 56→                .timeout(timeout)
 57→                .build()
 58→                .expect("Failed to build HTTP client"),
 59→            timeout,
 60→            max_response_size,
 61→        }
 62→    }
 63→
 64→    /// Get the configured timeout.
 65→    pub fn timeout(&self) -> Duration {
 66→        self.timeout
 67→    }
 68→
 69→    /// Fetch a template from a URL.
 70→    pub fn fetch(&self, url: &str) -> Result<FetchResponse> {
 71→        let response = self.client.get(url).send()?;
 72→
 73→        if !response.status().is_success() {
 74→            bail!("HTTP {} fetching {}", response.status(), url);
 75→        }
 76→
 77→        // Check Content-Length if available
 78→        if let Some(len) = response.content_length() {
 79→            if len > self.max_response_size {
 80→                bail!(
 81→                    "Response too large ({} bytes, max {} bytes) from {}",
 82→                    len,
 83→                    self.max_response_size,
 84→                    url
 85→                );
 86→            }
 87→        }
 88→
 89→        let etag = response
 90→            .headers()
 91→            .get("etag")
 92→            .and_then(|v| v.to_str().ok())
 93→            .map(String::from);
 94→
 95→        let last_modified = response
 96→            .headers()
 97→            .get("last-modified")
 98→            .and_then(|v| v.to_str().ok())
 99→            .map(String::from);
100→
101→        let content = response.text()?;
102→
103→        // Also check actual content size (in case Content-Length was missing/wrong)
104→        if content.len() as u64 > self.max_response_size {
105→            bail!(
106→                "Response too large ({} bytes, max {} bytes) from {}",
107→                content.len(),
108→                self.max_response_size,
109→                url
110→            );
111→        }
112→
113→        Ok(FetchResponse {
114→            content,
115→            etag,
116→            last_modified,
117→        })
118→    }
119→
120→    /// Fetch with conditional request (If-None-Match).
121→    ///
122→    /// Returns `None` if content unchanged (304 Not Modified).
123→    pub fn fetch_if_changed(&self, url: &str, etag: Option<&str>) -> Result<Option<FetchResponse>> {
124→        let mut request = self.client.get(url);
125→
126→        if let Some(etag) = etag {
127→            request = request.header("If-None-Match", etag);
128→        }
129→
130→        let response = request.send()?;
131→
132→        if response.status() == reqwest::StatusCode::NOT_MODIFIED {
133→            return Ok(None);
134→        }
135→
136→        if !response.status().is_success() {
137→            bail!("HTTP {} fetching {}", response.status(), url);
138→        }
139→
140→        // Check Content-Length if available
141→        if let Some(len) = response.content_length() {
142→            if len > self.max_response_size {
143→                bail!(
144→                    "Response too large ({} bytes, max {} bytes) from {}",
145→                    len,
146→                    self.max_response_size,
147→                    url
148→                );
149→            }
150→        }

  1→//! Remote configuration fetching.
  2→//!
  3→//! This module provides functionality for fetching configuration files
  4→//! from remote URLs.
  5→
  6→use anyhow::{anyhow, Context, Result};
  7→use std::collections::HashMap;
  8→use std::path::PathBuf;
  9→use std::time::Duration;
 10→
 11→/// Fetches remote configuration files with caching.
 12→///
 13→/// # Example
 14→///
 15→/// ```no_run
 16→/// use bivvy::config::RemoteFetcher;
 17→/// use std::time::Duration;
 18→///
 19→/// let fetcher = RemoteFetcher::new(Duration::from_secs(30));
 20→///
 21→/// // Fetch a remote config file
 22→/// let content = fetcher.fetch("https://example.com/config.yml").unwrap();
 23→/// ```
 24→pub struct RemoteFetcher {
 25→    /// Request timeout.
 26→    timeout: Duration,
 27→    /// Cache directory for downloaded configs.
 28→    cache_dir: PathBuf,
 29→    /// HTTP client.
 30→    client: reqwest::blocking::Client,
 31→}
 32→
 33→impl RemoteFetcher {
 34→    /// Create a fetcher with the specified timeout.
 35→    pub fn new(timeout: Duration) -> Self {
 36→        let cache_dir = dirs::cache_dir()
 37→            .unwrap_or_else(|| PathBuf::from("~/.cache"))
 38→            .join("bivvy")
 39→            .join("remote-configs");
 40→
 41→        Self {
 42→            timeout,
 43→            cache_dir,
 44→            client: reqwest::blocking::Client::builder()
 45→                .timeout(timeout)
 46→                .build()
 47→                .expect("Failed to create HTTP client"),
 48→        }
 49→    }
 50→
 51→    /// Create a fetcher with a custom cache directory.
 52→    pub fn with_cache_dir(timeout: Duration, cache_dir: PathBuf) -> Self {
 53→        Self {
 54→            timeout,
 55→            cache_dir,
 56→            client: reqwest::blocking::Client::builder()
 57→                .timeout(timeout)
 58→                .build()
 59→                .expect("Failed to create HTTP client"),
 60→        }
 61→    }
 62→
 63→    /// Fetch a configuration file from a URL.
 64→    pub fn fetch(&self, url: &str) -> Result<String> {
 65→        // Check cache first
 66→        if let Some(cached) = self.check_cache(url)? {
 67→            return Ok(cached);
 68→        }
 69→
 70→        // Fetch from remote
 71→        let content = self.fetch_remote(url)?;
 72→
 73→        // Cache the result
 74→        self.save_cache(url, &content)?;
 75→
 76→        Ok(content)
 77→    }
 78→
 79→    /// Fetch a configuration file, bypassing cache.
 80→    pub fn fetch_fresh(&self, url: &str) -> Result<String> {
 81→        self.fetch_remote(url)
 82→    }
 83→
 84→    /// Fetch with authentication header.
 85→    pub fn fetch_with_auth(&self, url: &str, auth: &AuthHeader) -> Result<String> {
 86→        let response = self
 87→            .client
 88→            .get(url)
 89→            .header(&auth.header_name, &auth.header_value)
 90→            .send()
 91→            .with_context(|| format!("Failed to fetch {}", url))?;
 92→
 93→        if !response.status().is_success() {
 94→            return Err(anyhow!("HTTP {} fetching {}", response.status(), url));
 95→        }
 96→
 97→        response
 98→            .text()
 99→            .with_context(|| format!("Failed to read response from {}", url))
100→    }
101→
102→    fn fetch_remote(&self, url: &str) -> Result<String> {
103→        let response = self
104→            .client
105→            .get(url)
106→            .send()
107→            .with_context(|| format!("Failed to fetch {}", url))?;
108→
109→        if !response.status().is_success() {
110→            return Err(anyhow!("HTTP {} fetching {}", response.status(), url));
111→        }
112→
113→        response
114→            .text()
115→            .with_context(|| format!("Failed to read response from {}", url))
116→    }
117→
118→    fn check_cache(&self, url: &str) -> Result<Option<String>> {
119→        let cache_path = self.cache_path(url);
120→        if cache_path.exists() {
121→            let content = std::fs::read_to_string(&cache_path)?;
122→            Ok(Some(content))
123→        } else {
124→            Ok(None)
125→        }
126→    }
127→
128→    fn save_cache(&self, url: &str, content: &str) -> Result<()> {
129→        let cache_path = self.cache_path(url);
130→        if let Some(parent) = cache_path.parent() {
131→            std::fs::create_dir_all(parent)?;
132→        }
133→        std::fs::write(&cache_path, content)?;
134→        Ok(())
135→    }
136→
137→    fn cache_path(&self, url: &str) -> PathBuf {
138→        use sha2::{Digest, Sha256};
139→        let mut hasher = Sha256::new();
140→        hasher.update(url.as_bytes());
141→        let hash = hex::encode(hasher.finalize());
142→        self.cache_dir.join(format!("{}.yml", hash))
143→    }
144→
145→    /// Clear the cache for a specific URL.
146→    pub fn clear_cache(&self, url: &str) -> Result<()> {
147→        let cache_path = self.cache_path(url);
148→        if cache_path.exists() {
149→            std::fs::remove_file(&cache_path)?;
150→        }
151→        Ok(())
152→    }
153→
154→    /// Clear all cached configurations.
155→    pub fn clear_all_cache(&self) -> Result<()> {
156→        if self.cache_dir.exists() {
157→            std::fs::remove_dir_all(&self.cache_dir)?;
158→        }
159→        Ok(())
160→    }
161→
162→    /// Get the request timeout.
163→    pub fn timeout(&self) -> Duration {
164→        self.timeout
165→    }
166→}
167→
168→impl Default for RemoteFetcher {
169→    fn default() -> Self {
170→        Self::new(Duration::from_secs(30))
171→    }
172→}
