    #[test]
    fn concurrent_stores_to_same_key_no_corruption() {
        let temp = TempDir::new().unwrap();
        let root = temp.path().to_path_buf();

        let handles: Vec<_> = (0..8)
            .map(|i| {
                let root = root.clone();
                std::thread::spawn(move || {
                    let store = CacheStore::new(&root);
                    let content = format!("content from thread {}", i);
                    store
                        .store("http:test", "shared-template", &content, 3600)
                        .unwrap();
                })
            })
            .collect();

        for handle in handles {
            handle.join().unwrap();
        }

        // After all threads finish, the cache must be in a valid state:
        // metadata must be parseable and content must be readable and
        // internally consistent.
        let store = CacheStore::new(temp.path());
        let entry = store
            .load("http:test", "shared-template")
            .unwrap()
            .expect("entry should exist");
        let content = store.read_content(&entry).unwrap();

        assert!(
            content.starts_with("content from thread "),
            "content should be one complete write, got: {:?}",
            content
        );
        assert_eq!(entry.metadata.size_bytes, content.len() as u64);
    }

    #[test]
    fn concurrent_stores_to_different_keys_no_corruption() {
        let temp = TempDir::new().unwrap();
        let root = temp.path().to_path_buf();

        let handles: Vec<_> = (0..8)
            .map(|i| {
                let root = root.clone();
                std::thread::spawn(move || {
                    let store = CacheStore::new(&root);
                    let name = format!("template-{}", i);
                    let content = format!("content-{}", i);
                    store
                        .store("http:test", &name, &content, 3600)
                        .unwrap();
                })
            })
            .collect();

        for handle in handles {
            handle.join().unwrap();
        }

        let store = CacheStore::new(temp.path());
        let entries = store.list().unwrap();
        assert_eq!(entries.len(), 8);

        for i in 0..8 {
            let name = format!("template-{}", i);
            let expected = format!("content-{}", i);
            let entry = store
                .load("http:test", &name)
                .unwrap()
                .expect("entry should exist");
            let content = store.read_content(&entry).unwrap();
            assert_eq!(content, expected);
            assert_eq!(entry.metadata.size_bytes, expected.len() as u64);
        }
    }

    #[test]
    fn no_temp_files_left_after_store() {
        let temp = TempDir::new().unwrap();
        let store = CacheStore::new(temp.path());

        store
            .store("http:test", "template1", "content", 3600)
            .unwrap();

        // Count files in the cache directory: should be exactly 2
        // (one content file and one .meta.json file), no .tmp files.
        let file_count = fs::read_dir(temp.path())
            .unwrap()
            .filter_map(|e| e.ok())
            .filter(|e| {
                e.path()
                    .to_string_lossy()
                    .contains(".tmp")
            })
            .count();

        assert_eq!(file_count, 0, "no temporary files should remain");
    }

    #[test]
    fn concurrent_store_and_load_no_corruption() {
        let temp = TempDir::new().unwrap();
        let root = temp.path().to_path_buf();

        // Seed the cache with an initial entry.
        let store = CacheStore::new(&root);
        store
            .store("http:test", "shared", "initial", 3600)
            .unwrap();

        let handles: Vec<_> = (0..8)
            .map(|i| {
                let root = root.clone();
                std::thread::spawn(move || {
                    let store = CacheStore::new(&root);
                    if i % 2 == 0 {
                        // Writers
                        let content = format!("writer-{}", i);
                        store
                            .store("http:test", "shared", &content, 3600)
                            .unwrap();
                    } else {
                        // Readers: load + read_content must always succeed
                        // if the entry exists.
                        for _ in 0..20 {
                            if let Ok(Some(entry)) = store.load("http:test", "shared") {
                                let content = store.read_content(&entry).unwrap();
                                // Content must be a complete string, never partial.
                                assert!(
                                    content == "initial" || content.starts_with("writer-"),
                                    "content was corrupted: {:?}",
                                    content
                                );
                            }
                            std::thread::yield_now();
                        }
                    }
                })
            })
            .collect();

        for handle in handles {
            handle.join().unwrap();
        }
    }
}

